<script setup>
import './assets/bootstrap.min.css';
import {ref} from "vue";
import {getRandomInt, initAndPlayBeep} from "@/assets/utils.js";

const snd = new Audio("data:audio/wav;base64,");
const genius = ref([]);
const userGenius = ref([]);
const currentBeep = ref(null);
const timeBetween = 600;
const pressable = ref(false);
const wrong = ref(false);
const delay = ms => new Promise(res => setTimeout(res, ms));

function beep() {
  snd.play();
}

async function gameStart() {
  genius.value = [];
  userGenius.value = [];
  let randomValue = generateValue();
  genius.value.push(randomValue);
  beep();
  currentBeep.value = randomValue;
  await delay(timeBetween);
  resetValue();
}

function resetValue() {
  currentBeep.value = null;
  pressable.value = true;
}

function generateValue() {
  return getRandomInt(0, 4);
}

async function nextRound() {
  pressable.value = false;
  userGenius.value = [];
  let randomValue = generateValue();
  genius.value.push(randomValue);

  for (let i = 0; i < genius.value.length; i++) {
    let currentColor = genius.value[i];
    await delay(timeBetween);
    beep();
    currentBeep.value = currentColor;
  }

  await delay(timeBetween);
  resetValue();
  pressable.value = true;
}

async function missGame() {
  wrong.value = true;
  initAndPlayBeep()
  await delay(1000);

  wrong.value = false;
  gameStart()
}

function pressColor(index) {
  if (!pressable.value) return null;
  userGenius.value.push(index);
  let lastItem = userGenius.value.length - 1;
  let miss = genius.value[lastItem] === userGenius.value[lastItem]
  currentBeep.value = index;
  beep();
  setTimeout(resetValue, timeBetween)
  if (!miss) {
    missGame();
  } else if (genius.value.length === userGenius.value.length) {
    setTimeout(nextRound, 1000);
  }
}
</script>

<template>
  <div class="container mt-3 col-md-4 col-12">
    <div class="container-genius">
      <button @click="()=>pressColor(0)" class="btn-side btn-red" :class="{
        'btn-red-light': currentBeep === 0 || wrong
      }"></button>
      <button @click="()=>pressColor(1)" class="btn-side btn-green" :class="{
      'btn-green-light': currentBeep === 1 || wrong
      }"></button>
      <button @click="()=>pressColor(2)" class="btn-side btn-blue" :class="{
        'btn-blue-light': currentBeep === 2 || wrong
      }"></button>
      <button @click="()=>pressColor(3)" class="btn-side btn-yellow" :class="{
      'btn-yellow-light': currentBeep === 3 || wrong
      }"></button>
      <button class="btn btn-start btn-primary" @click="gameStart">Start {{ genius.length }}</button>
    </div>
  </div>
</template>

