.container-genius {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: repeat(2, 1fr);
  gap: .5rem;
  position: relative;
  border-radius: 50%;
  aspect-ratio: 1/1;
  overflow: hidden;
}

.btn-side {
  width: 100%;
  height: 100%;
  border: none;
  transition: .1s;
}

.btn-red {
  background: red;
}

.btn-green {
  background: green;
}

.btn-blue {
  background: blue;
}

.btn-yellow {
  background: yellow;
}

.btn-red-light {
  background: orangered;
}

.btn-green-light {
  background: lightgreen;
}

.btn-blue-light {
  background: lightblue;
}

.btn-yellow-light {
  background: lightyellow;
}


.btn-start {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translateX(-50%) translateY(-50%);
  border-radius: 50%;
